/* Writes vendor/v4-sources.json: every Uniswap V4 source file the templates
   import, keyed by import path. The builder's in-browser compiler gets these
   as standard-JSON sources, so it never needs to fetch an import.

     npm i --no-save solc@0.8.26 @uniswap/v4-core@1.0.2 @uniswap/v4-periphery@1.0.3
     node scripts/bundle-v4-sources.js

   Re-run after changing an import in builder.js. */

const fs = require('fs');
const path = require('path');
const solc = require('solc');
const B = require('../builder.js');

const used = {};
const readImport = (p) => {
  try {
    const contents = fs.readFileSync(require.resolve(p, { paths: [process.cwd(), __dirname] }), 'utf8');
    used[p] = contents;
    return { contents };
  } catch (_) {
    return { error: `not found: ${p}` };
  }
};

const ADDR = '0x1111111111111111111111111111111111111111';
for (const recipe of Object.keys(B.RECIPES)) {
  const out = B.generate(recipe, { recipient: ADDR, token: ADDR });
  const res = JSON.parse(solc.compile(JSON.stringify({
    language: 'Solidity',
    sources: { [out.file]: { content: out.source } },
    settings: { evmVersion: 'cancun', outputSelection: { '*': { '*': [] } } }
  }), { import: readImport }));
  const errors = (res.errors || []).filter((e) => e.severity === 'error');
  if (errors.length) { console.error(errors.map((e) => e.formattedMessage).join('\n')); process.exit(1); }
}

const file = path.join(__dirname, '..', 'vendor', 'v4-sources.json');
const sorted = Object.fromEntries(Object.keys(used).sort().map((k) => [k, used[k]]));
fs.writeFileSync(file, JSON.stringify({
  note: 'Uniswap V4 sources imported by the UnyHooks templates (v4-core 1.0.2, v4-periphery 1.0.3). Each file keeps its own SPDX licence header. Generated by scripts/bundle-v4-sources.js.',
  sources: sorted
}));
console.log(`${Object.keys(sorted).length} files, ${(fs.statSync(file).size / 1024).toFixed(0)} KB -> vendor/v4-sources.json`);
